-- RRTrack 2.0 - ATUALIZAR-2026-09-30-E-COMPACTO (versao compacta)
-- O SQL Editor do Supabase corta o script na linha 100; esta versao cabe.
-- Mesmo conteudo de ATUALIZAR-2026-09-30-E.sql, sem as quebras de linha. Cole tudo e rode.

alter table public.visitors add column if not exists gclid text; alter table public.visitors add column if not exists wbraid text; alter table public.purchases add column if not exists gclid text; alter table public.purchases add column if not exists wbraid text; comment on column public.visitors.gclid is 'O Google click ID, cru, como veio na URL da visita. Não dá para reconstruir depois: chega uma vez e nem o checkout nem o gateway o conhecem. NULL = a visita não veio de clique do Google Ads.'; comment on column public.visitors.wbraid is 'O identificador de clique WEB do Google quando o consentimento limita o gclid — o proto do ClickConversion chama assim. Guardar só o gclid perderia justamente o clique restringido pela privacidade. O gbraid (campanha de APP) não é capturado: a loja não tem aplicativo.'; comment on column public.purchases.gclid is 'O gclid que valia na HORA DA COMPRA, copiado do visitante no casamento. Congelado aqui porque visitors guarda só o da última visita, e uma volta por outro anúncio reescreveria o clique que gerou esta venda.'; comment on column public.purchases.wbraid is 'O wbraid que valia na hora da compra. Mesma razão do gclid ao lado.'; grant select (gclid, wbraid) on public.visitors to authenticated; grant select (gclid, wbraid) on public.purchases to authenticated;
